import 'package:flutter/material.dart';
import '../../data/models/dramatic_card_model.dart';

/// Represents a single curated daily general life dilemma definition • Day 1 to 365
class DailyLifeCardDef {
  final int day;
  final DramaticCategory category;
  final DramaticSeverity severity;
  final String title;
  final String dialogue;
  final String characterName;
  final String characterRole;
  final String characterAvatar;
  final IconData icon;
  final String foreshadowHint;
  final String choice1Label;
  final String choice1Desc;
  final double choice1Cost;
  final String choice1OutcomeTitle;
  final String choice1OutcomeMsg;
  final int choice1Rep;
  final double choice1Money;
  final int choice1Xp;
  final String choice2Label;
  final String choice2Desc;
  final double choice2Cost;
  final String choice2OutcomeTitle;
  final String choice2OutcomeMsg;
  final int choice2Rep;
  final double choice2Money;
  final int choice2Xp;

  const DailyLifeCardDef({
    required this.day,
    required this.category,
    this.severity = DramaticSeverity.medium,
    required this.title,
    required this.dialogue,
    required this.characterName,
    required this.characterRole,
    required this.characterAvatar,
    required this.icon,
    required this.foreshadowHint,
    required this.choice1Label,
    required this.choice1Desc,
    this.choice1Cost = 0.0,
    required this.choice1OutcomeTitle,
    required this.choice1OutcomeMsg,
    this.choice1Rep = 0,
    this.choice1Money = 0.0,
    this.choice1Xp = 25,
    required this.choice2Label,
    required this.choice2Desc,
    this.choice2Cost = 0.0,
    required this.choice2OutcomeTitle,
    required this.choice2OutcomeMsg,
    this.choice2Rep = 0,
    this.choice2Money = 0.0,
    this.choice2Xp = 20,
  });

  DramaticCardModel toCard(int dayNumber) {
    return DramaticCardModel(
      id: 'life_card_day_$day',
      dayNumber: dayNumber,
      category: category,
      severity: severity,
      title: title,
      characterName: characterName,
      characterRole: characterRole,
      characterAvatar: characterAvatar,
      icon: icon,
      dialogue: dialogue,
      foreshadowHint: foreshadowHint,
      choices: [
        DramaticChoiceModel(
          id: 'c1_day_$day',
          label: choice1Label,
          shortDescription: choice1Desc,
          upfrontCost: choice1Cost,
          outcomes: [
            DramaticOutcomeModel(
              probability: 1.0,
              title: choice1OutcomeTitle,
              message: choice1OutcomeMsg,
              isSuccess: choice1Rep >= 0 && choice1Money >= 0,
              reputationDelta: choice1Rep,
              moneyDelta: choice1Money,
              xpReward: choice1Xp,
            ),
          ],
        ),
        DramaticChoiceModel(
          id: 'c2_day_$day',
          label: choice2Label,
          shortDescription: choice2Desc,
          upfrontCost: choice2Cost,
          outcomes: [
            DramaticOutcomeModel(
              probability: 1.0,
              title: choice2OutcomeTitle,
              message: choice2OutcomeMsg,
              isSuccess: choice2Rep >= 0 && choice2Money >= 0,
              reputationDelta: choice2Rep,
              moneyDelta: choice2Money,
              xpReward: choice2Xp,
            ),
          ],
        ),
      ],
    );
  }
}

